## debounce 函式

```javascript
/**
 * 建立一個 debounce 包裝函式：在最後一次呼叫後等待 `delay` 毫秒才真正執行。
 * @param {Function} fn - 要被防抖的函式
 * @param {number} delay - 等待時間（毫秒）
 * @param {boolean} [immediate=false] - 若為 true，則在第一次呼叫時立即執行，之後等待期間內不再執行
 * @returns {Function} 防抖後的函式，附帶 cancel() 方法
 */
function debounce(fn, delay = 300, immediate = false) {
  let timer = null;

  const debounced = function (...args) {
    const context = this;
    const callNow = immediate && !timer;

    clearTimeout(timer);

    timer = setTimeout(() => {
      timer = null;
      if (!immediate) {
        fn.apply(context, args);
      }
    }, delay);

    if (callNow) {
      fn.apply(context, args);
    }
  };

  // 取消尚未執行的呼叫
  debounced.cancel = function () {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}
```

## 使用範例

```javascript
// 1. 搜尋輸入框：停止輸入 500ms 後才送出搜尋
const searchInput = document.querySelector('#search');

const handleSearch = debounce((e) => {
  console.log('搜尋關鍵字：', e.target.value);
}, 500);

searchInput.addEventListener('input', handleSearch);

// 2. 視窗縮放：縮放結束 200ms 後才重新計算版面
const handleResize = debounce(() => {
  console.log('視窗寬度：', window.innerWidth);
}, 200);

window.addEventListener('resize', handleResize);

// 3. immediate 模式：第一次點擊立即執行，之後 1 秒內的重複點擊會被忽略
const handleClick = debounce(() => {
  console.log('送出表單');
}, 1000, true);

document.querySelector('#submit').addEventListener('click', handleClick);

// 4. 取消待執行的呼叫
handleSearch.cancel();
```

## 說明

- **一般模式**（預設）：每次呼叫都會重設計時器，只有在停止呼叫 `delay` 毫秒後才執行一次。適合搜尋建議、表單驗證等。
- **immediate 模式**：第一次呼叫立即執行，之後在靜默期內的呼叫都會被忽略。適合防止按鈕重複送出。
- **保留 `this` 與參數**：透過 `fn.apply(context, args)` 確保原函式的 `this` 和傳入參數正確。
- **`cancel()`**：可在元件卸載或不再需要時取消待執行的呼叫，避免記憶體或邏輯上的問題。

```javascript
function debounce(fn, delay) {
  let timer = null;

  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      fn.apply(this, args);
    }, delay);
  };
}
```

**使用範例：**

```javascript
const onSearch = debounce((keyword) => {
  console.log("搜尋：", keyword);
}, 300);

onSearch("a");
onSearch("ab");
onSearch("abc"); // 只有最後一次呼叫會在 300ms 後執行，輸出：搜尋： abc
```

**說明：** 每次呼叫都會清除前一個計時器，只有在停止呼叫 `delay` 毫秒後，才會執行一次 `fn`。

（寫好 debounce，附上範例）

```javascript
function debounce(fn, delay) {
  let timer = null;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}
```

使用範例：

```javascript
const onSearch = debounce((query) => {
  console.log('搜尋：', query);
}, 300);

onSearch('a');
onSearch('ab');
onSearch('abc'); // 只有最後一次呼叫會在 300ms 後執行：搜尋： abc
```

每次呼叫都會清除前一個計時器，只有停止呼叫滿 `delay` 毫秒後，`fn` 才會執行一次。

```javascript
/**
 * 建立一個 debounce 函式：在最後一次呼叫後等待 `wait` 毫秒才真正執行。
 * @param {Function} fn - 要被 debounce 的函式
 * @param {number} wait - 等待時間（毫秒）
 * @param {boolean} [immediate=false] - 若為 true，則在第一次呼叫時立即執行，之後的呼叫在靜默期結束前被忽略
 * @returns {Function} 包裝後的函式，並附有 cancel() 與 flush() 方法
 */
function debounce(fn, wait = 300, immediate = false) {
  let timer = null;
  let lastArgs = null;
  let lastThis = null;

  function debounced(...args) {
    lastArgs = args;
    lastThis = this;

    const callNow = immediate && timer === null;

    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!immediate) {
        fn.apply(lastThis, lastArgs);
      }
      lastArgs = lastThis = null;
    }, wait);

    if (callNow) {
      fn.apply(this, args);
    }
  }

  // 取消尚未執行的呼叫
  debounced.cancel = () => {
    clearTimeout(timer);
    timer = lastArgs = lastThis = null;
  };

  // 立即執行尚未觸發的呼叫
  debounced.flush = () => {
    if (timer === null) return;
    clearTimeout(timer);
    timer = null;
    if (lastArgs) {
      fn.apply(lastThis, lastArgs);
    }
    lastArgs = lastThis = null;
  };

  return debounced;
}

// ===== 使用範例 =====

// 1. 基本用法：搜尋框輸入，停止輸入 500ms 後才送出請求
const searchInput = { value: '' };

function searchAPI(keyword) {
  console.log(`搜尋：${keyword}`);
}

const debouncedSearch = debounce(searchAPI, 500);

// 模擬使用者連續輸入（只有最後一次會在 500ms 後執行）
debouncedSearch('j');
debouncedSearch('ja');
debouncedSearch('jav');
debouncedSearch('javascript');
// 輸出：搜尋：javascript（約 500ms 後）

// 2. 立即執行模式：第一次立刻執行，之後靜默期內的呼叫會被忽略
const onClick = debounce(() => console.log('按鈕被點擊'), 1000, true);

onClick(); // 立即輸出「按鈕被點擊」
onClick(); // 被忽略
onClick(); // 被忽略

// 3. 取消與立即執行
const save = debounce(() => console.log('已儲存'), 2000);

save();
save.flush();  // 立即執行，輸出「已儲存」
save();
save.cancel(); // 取消，不會輸出
```

**說明：**
- **基本模式**：每次呼叫都會重設計時器，只有在停止呼叫 `wait` 毫秒後才執行最後一次。適用於搜尋輸入、視窗 resize 等情境。
- **immediate 模式**：第一次呼叫立即執行，之後在靜默期內的呼叫被忽略。適用於防止按鈕重複點擊。
- **cancel()**：取消待執行的呼叫。
- **flush()**：立即執行待執行的呼叫。
- 使用 `this` 與參數的傳遞會保留原始呼叫時的上下文。

```javascript
function debounce(fn, delay) {
  let timer = null;

  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      fn.apply(this, args);
    }, delay);
  };
}
```

**使用範例：**

```javascript
const onSearch = debounce((keyword) => {
  console.log("搜尋：", keyword);
}, 300);

// 連續輸入時，只有最後一次在停止 300ms 後會執行
onSearch("h");
onSearch("he");
onSearch("hel");
onSearch("hello"); // 只有這次會輸出：搜尋： hello
```

**說明：** 每次呼叫都會清除前一次的計時器並重新計時，因此函式只會在最後一次呼叫後等待 `delay` 毫秒才執行。

